import { Plus, Trash2 } from 'lucide-react';
import { btnSecondary, inputClass } from '@/components/common/ui';
import type { CourseOptions } from '@/types/course';
import type { ContentForm } from './courseForm';
import Field from './Field';

interface Props {
  value: ContentForm;
  options: CourseOptions | null;
  onChange: (patch: Partial<ContentForm>) => void;
}

const area = `${inputClass} min-h-[5.5rem] resize-y`;

/** "Course page" tab: everything shown on the course details page. Empty parts are generated by the website. */
export default function CourseContentTab({ value: v, options, onChange }: Props) {
  const setInstructor = (patch: Partial<ContentForm['instructor']>) => onChange({ instructor: { ...v.instructor, ...patch } });
  const setModule = (i: number, patch: Partial<ContentForm['curriculum'][number]>) => onChange({ curriculum: v.curriculum.map((m, n) => (n === i ? { ...m, ...patch } : m)) });
  const setFaq = (i: number, patch: Partial<ContentForm['faqs'][number]>) => onChange({ faqs: v.faqs.map((f, n) => (n === i ? { ...f, ...patch } : f)) });
  const toggleHighlight = (key: string) => onChange({ highlights: v.highlights.includes(key) ? v.highlights.filter((k) => k !== key) : [...v.highlights, key] });

  return (
    <div className="space-y-5">
      <p className="rounded-xl border border-gold/30 bg-peach/60 px-3.5 py-2.5 text-[0.8rem] leading-snug text-veda-bark">
        This text appears on the course details page. <b>Leave a part empty</b> and the website writes it automatically.
      </p>

      <Field label="Tagline" optional hint="One line under the course name." >
        <input value={v.tagline} onChange={(e) => onChange({ tagline: e.target.value })} maxLength={200} className={inputClass} />
      </Field>

      <Field label="About this course" optional>
        <textarea value={v.about} onChange={(e) => onChange({ about: e.target.value })} maxLength={2000} className={`${area} min-h-[8rem]`} />
      </Field>

      <div>
        <span className="mb-1.5 block text-[0.8rem] font-semibold text-veda-bark">
          Highlights <span className="font-normal text-veda-muted">(ticks under “About”)</span>
        </span>
        <div className="flex flex-wrap gap-2">
          {(options?.highlights ?? []).map((h) => {
            const on = v.highlights.includes(h.key);
            return (
              <button
                key={h.key}
                type="button"
                aria-pressed={on}
                onClick={() => toggleHighlight(h.key)}
                className={`rounded-full border px-3 py-1.5 text-[0.78rem] font-medium transition ${on ? 'border-saffron bg-saffron text-white' : 'border-line bg-white/70 text-veda-text hover:border-gold'}`}
              >
                {h.label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="What you will learn" optional hint="One point per line.">
          <textarea value={v.learn} onChange={(e) => onChange({ learn: e.target.value })} className={`${area} min-h-[9rem]`} />
        </Field>
        <Field label="Who is this course for" optional hint="One point per line.">
          <textarea value={v.audience} onChange={(e) => onChange({ audience: e.target.value })} className={`${area} min-h-[9rem]`} />
        </Field>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <Field label="Topic tags" optional hint="One per line, e.g. Live Classes.">
          <textarea value={v.tags} onChange={(e) => onChange({ tags: e.target.value })} className={area} />
        </Field>
        <div className="space-y-4">
          <Field label="Number of ratings" optional hint="Shown as “4.8 (980)”.">
            <input inputMode="numeric" value={v.ratingCount} onChange={(e) => onChange({ ratingCount: e.target.value.replace(/\D/g, '') })} className={inputClass} />
          </Field>
          <Field label="Phone banner text" optional>
            <input value={v.bannerTitle} onChange={(e) => onChange({ bannerTitle: e.target.value })} maxLength={80} className={inputClass} />
          </Field>
        </div>
      </div>

      {/* curriculum */}
      <section>
        <div className="mb-2 flex items-center justify-between gap-3">
          <h3 className="font-display text-[1.05rem] font-bold text-veda-bark">Curriculum</h3>
          <button type="button" onClick={() => onChange({ curriculum: [...v.curriculum, { title: '', lessons: '', weeks: '', topics: '' }] })} className={`${btnSecondary} !px-3 !py-1.5`}>
            <Plus size={15} aria-hidden /> Add module
          </button>
        </div>
        {v.curriculum.length === 0 && <p className="text-[0.8rem] text-veda-muted">No modules added: the website shows an automatic outline based on lessons and weeks.</p>}
        <ol className="space-y-3">
          {v.curriculum.map((m, i) => (
            <li key={i} className="space-y-2.5 rounded-xl border border-line bg-white/60 p-3">
              <div className="flex items-center gap-2">
                <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-peach text-[0.78rem] font-bold text-saffron">{i + 1}</span>
                <input value={m.title} onChange={(e) => setModule(i, { title: e.target.value })} placeholder="Module title" maxLength={120} aria-label={`Module ${i + 1} title`} className={inputClass} />
                <button type="button" onClick={() => onChange({ curriculum: v.curriculum.filter((_, n) => n !== i) })} aria-label={`Remove module ${i + 1}`} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-red-700 hover:bg-red-50">
                  <Trash2 size={16} />
                </button>
              </div>
              <div className="grid grid-cols-2 gap-2.5">
                <input inputMode="numeric" value={m.lessons} onChange={(e) => setModule(i, { lessons: e.target.value.replace(/\D/g, '') })} placeholder="Lessons" aria-label={`Module ${i + 1} lessons`} className={inputClass} />
                <input inputMode="numeric" value={m.weeks} onChange={(e) => setModule(i, { weeks: e.target.value.replace(/\D/g, '') })} placeholder="Weeks" aria-label={`Module ${i + 1} weeks`} className={inputClass} />
              </div>
              <textarea value={m.topics} onChange={(e) => setModule(i, { topics: e.target.value })} placeholder="Topics (one per line)" aria-label={`Module ${i + 1} topics`} className={area} />
            </li>
          ))}
        </ol>
      </section>

      {/* instructor box */}
      <section className="space-y-3">
        <h3 className="font-display text-[1.05rem] font-bold text-veda-bark">Instructor box</h3>
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label="Title" optional>
            <input value={v.instructor.title} onChange={(e) => setInstructor({ title: e.target.value })} placeholder="e.g. Vedic Astrology Expert" maxLength={80} className={inputClass} />
          </Field>
          <Field label="Experience" optional>
            <input value={v.instructor.experience} onChange={(e) => setInstructor({ experience: e.target.value })} placeholder="e.g. 15+ Years of Experience" maxLength={80} className={inputClass} />
          </Field>
        </div>
        <Field label="Bio" optional hint="Write {name} where the instructor's name should appear.">
          <textarea value={v.instructor.bio} onChange={(e) => setInstructor({ bio: e.target.value })} maxLength={600} className={area} />
        </Field>
        <div className="grid grid-cols-3 gap-3">
          <Field label="Courses">
            <input inputMode="numeric" value={v.instructor.coursesConducted} onChange={(e) => setInstructor({ coursesConducted: e.target.value.replace(/\D/g, '') })} className={inputClass} />
          </Field>
          <Field label="Students">
            <input inputMode="numeric" value={v.instructor.students} onChange={(e) => setInstructor({ students: e.target.value.replace(/\D/g, '') })} className={inputClass} />
          </Field>
          <Field label="Rating (0-5)">
            <input inputMode="decimal" value={v.instructor.rating} onChange={(e) => setInstructor({ rating: e.target.value.replace(/[^\d.]/g, '') })} className={inputClass} />
          </Field>
        </div>
      </section>

      {/* faqs */}
      <section>
        <div className="mb-2 flex items-center justify-between gap-3">
          <h3 className="font-display text-[1.05rem] font-bold text-veda-bark">FAQs</h3>
          <button type="button" onClick={() => onChange({ faqs: [...v.faqs, { q: '', a: '' }] })} className={`${btnSecondary} !px-3 !py-1.5`}>
            <Plus size={15} aria-hidden /> Add FAQ
          </button>
        </div>
        {v.faqs.length === 0 && <p className="text-[0.8rem] text-veda-muted">No FAQs added: the website shows its standard questions.</p>}
        <ul className="space-y-3">
          {v.faqs.map((f, i) => (
            <li key={i} className="space-y-2.5 rounded-xl border border-line bg-white/60 p-3">
              <div className="flex items-center gap-2">
                <input value={f.q} onChange={(e) => setFaq(i, { q: e.target.value })} placeholder="Question" maxLength={160} aria-label={`FAQ ${i + 1} question`} className={inputClass} />
                <button type="button" onClick={() => onChange({ faqs: v.faqs.filter((_, n) => n !== i) })} aria-label={`Remove FAQ ${i + 1}`} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg text-red-700 hover:bg-red-50">
                  <Trash2 size={16} />
                </button>
              </div>
              <textarea value={f.a} onChange={(e) => setFaq(i, { a: e.target.value })} placeholder="Answer" maxLength={800} aria-label={`FAQ ${i + 1} answer`} className={area} />
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}